20		codeInvalidStateRequest = "invalid_state_request"
21		codeStateReadError      = "state_read_error"
22		codeStateWriteError     = "state_write_error"
23		codeStateLocked         = "state_locked"
24		codeStateConflict       = "state_conflict"
