package server

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"strconv"
	"sync/atomic"
)

// maxApplyAttempts bounds the controlled retry of one change: a RetryableError
// is retried in place until the change has been attempted three times.
const maxApplyAttempts = 3

// idempotencyRunCounter keeps keys unique across top-level requests even in
// the (practically impossible) case crypto/rand fails.
var idempotencyRunCounter atomic.Uint64

// newIdempotencyKeys returns one non-empty, mutually distinct key per change
// of a single top-level request. Every call produces a fresh run prefix, so a
// later request never reuses the keys of an earlier one; the retries of one
// change share its key.
func newIdempotencyKeys(count int) []string {
	var random [16]byte
	prefix := ""
	if _, err := rand.Read(random[:]); err == nil {
		prefix = hex.EncodeToString(random[:])
	}
	prefix += "-" + strconv.FormatUint(idempotencyRunCounter.Add(1), 10)

	keys := make([]string, count)
	for i := range keys {
		keys[i] = prefix + "/" + strconv.Itoa(i)
	}
	return keys
}

// applyChange executes one planned change through provider, retrying in place
// while the failure is a RetryableError reporting Retryable() true. Attempts
// are numbered 1..maxApplyAttempts and share the change's idempotency key; a
// plain error, a Retryable() false error, or the third failure is returned as
// is. Before a retry is prepared, a finished request context aborts the loop
// with the context's own error and no further Provider call.
func applyChange(ctx context.Context, provider Provider, change planChange, idempotencyKey string) error {
